import math


class Estimate:
    def __init__(self, value, var):
        self.value = value
        self.var = var

    def sigma(self):
        return math.sqrt(self.var)

    def fuse(self, other):
        w = 1.0 / self.var + 1.0 / other.var
        value = (self.value / self.var + other.value / other.var) / w
        return Estimate(value, 1.0 / w)


a = Estimate(1.204, 0.012 ** 2)
b = Estimate(1.191, 0.040 ** 2)
c = Estimate(1.213, 0.025 ** 2)
forward = a.fuse(b).fuse(c)
backward = c.fuse(b).fuse(a)
print("forward ", round(forward.value, 8), round(forward.sigma(), 8))
print("backward", round(backward.value, 8), round(backward.sigma(), 8))
print("same answer either way", abs(forward.value - backward.value) < 1e-12)
print("fused sigma below the best input", forward.sigma() < min(a.sigma(), b.sigma(), c.sigma()))

import math

DT = 0.01
Q_RATE = 0.0004
START_VAR = 0.0


def coast(seconds):
    var = START_VAR
    steps = int(round(seconds / DT))
    for _ in range(steps):
        var = var + Q_RATE * DT
    return var


for seconds in (1.0, 5.0, 10.0, 30.0):
    var = coast(seconds)
    print("coasting", seconds, "s  variance", round(var, 6), "sigma", round(math.sqrt(var), 4))

import math
import numpy as np

DT = 0.01
Q_RATE = 0.0004
RUNS = 4000


def predicted_sigma(seconds):
    return math.sqrt(Q_RATE * seconds)


def spread(seconds):
    rng = np.random.default_rng(77)
    steps = int(round(seconds / DT))
    step_sigma = math.sqrt(Q_RATE * DT)
    ends = []
    for _ in range(RUNS):
        x = 0.0
        for _ in range(steps):
            x = x + float(rng.normal(0.0, step_sigma))
        ends.append(x)
    centre = sum(ends) / len(ends)
    return math.sqrt(sum((e - centre) ** 2 for e in ends) / len(ends))


for seconds in (0.1, 0.5, 2.0):
    print("t", seconds, "predicted", round(predicted_sigma(seconds), 5), "measured", round(spread(seconds), 5))

