import math
import numpy as np

DT = 0.01
STEPS = 100
SIGMA_A = 0.30
F = np.array([[1.0, DT], [0.0, 1.0]])


def process_noise(dt, sigma_a):
    # TODO: build G for one tick and turn it into a covariance
    return np.zeros((2, 2))


def claimed_sigma(sigma_a):
    P = np.zeros((2, 2))
    Q = process_noise(DT, sigma_a)
    for _ in range(STEPS):
        P = F @ P @ F.T + Q
    return math.sqrt(float(P[0, 0]))


