import math
import numpy as np

EPS = 0.000001


def h(px, py, ax, ay):
    return math.sqrt((px - ax) ** 2 + (py - ay) ** 2)


def analytic(px, py, ax, ay):
    dx, dy = px - ax, py - ay
    r = math.sqrt(dx * dx + dy * dy)
    return np.array([[dx / r, dy / r]])


def forgot_to_divide(px, py, ax, ay):
    return np.array([[px - ax, py - ay]])


def numeric_jacobian(px, py, ax, ay):
    dr_dx = (h(px + EPS, py, ax, ay) - h(px - EPS, py, ax, ay)) / (2.0 * EPS)
    dr_dy = (h(px, py + EPS, ax, ay) - h(px, py - EPS, ax, ay)) / (2.0 * EPS)
    return np.array([[dr_dx, dr_dy]])


for px, py in ((3.0, 4.0), (0.5, 0.2)):
    num = numeric_jacobian(px, py, 0.0, 0.0)
    good = float(np.max(np.abs(num - analytic(px, py, 0.0, 0.0))))
    bad = float(np.max(np.abs(num - forgot_to_divide(px, py, 0.0, 0.0))))
    print("at", px, py, "analytic gap %.2e" % good, " gap of the one missing its division %.4f" % bad)

