import numpy as np

DT = 0.05
V = 0.9
OMEGA = 0.2
STEPS = 100
Q = np.diag([0.0001, 0.0001, 0.0004])


def transition_jacobian(theta, v, dt):
    # TODO: the identity plus the two entries that mix heading into position
    return np.eye(3)


def move(x, dt):
    theta = float(x[2, 0])
    return np.array([[float(x[0, 0]) + V * math.cos(theta) * dt],
