import math
import numpy as np

R = np.array([[0.02 ** 2]])
ANCHOR = (-6.0, -0.05)
TRUE = (0.0, 0.0)


def bearing(x, ax, ay):
    return math.atan2(float(x[1, 0]) - ay, float(x[0, 0]) - ax)


def jacobian(x, ax, ay):
    dx = float(x[0, 0]) - ax
    dy = float(x[1, 0]) - ay
    r2 = dx * dx + dy * dy
    return np.array([[-dy / r2, dx / r2]])


def wrap(a):
    return math.atan2(math.sin(a), math.cos(a))


def update(x, P, z, ax, ay, use_wrap):
    H = jacobian(x, ax, ay)
    y = float(z - bearing(x, ax, ay))
    if use_wrap:
        y = wrap(y)
    S = H @ P @ H.T + R
    K = P @ H.T @ np.linalg.inv(S)
    x = x + K * y
    P = (np.eye(2) - K @ H) @ P
    return x


z = math.atan2(TRUE[1] - ANCHOR[1], TRUE[0] - ANCHOR[0]) - 2.0 * math.pi
for use_wrap in (False, True):
    x = update(np.array([[0.2], [0.1]]), np.diag([0.5, 0.5]), z, ANCHOR[0], ANCHOR[1], use_wrap)
    err = math.sqrt((float(x[0, 0]) - TRUE[0]) ** 2 + (float(x[1, 0]) - TRUE[1]) ** 2)
    print("wrapped", use_wrap, "x", round(float(x[0, 0]), 3), "y", round(float(x[1, 0]), 3), "error", round(err, 3))

