import math
import numpy as np

STEP_CELLS = 20
CELL = 0.01
CELLS = np.linspace(-8.0, 8.0, 1601)
MOTION_SIGMA = 0.05
START_SIGMA = 0.20


def gaussian(values, centre, sigma):
    return np.exp(-0.5 * ((values - centre) / sigma) ** 2)


def make_kernel(sigma):
    half = int(round(4.0 * sigma / CELL))
    offsets = np.arange(-half, half + 1) * CELL
    k = gaussian(offsets, 0.0, sigma)
    return k / k.sum()


def predict(belief, kernel):
    # TODO: slide the belief along by STEP_CELLS, then spread it with the kernel
    moved = belief
    blurred = moved
    return blurred / blurred.sum()


def stats(belief):
    mean = float((CELLS * belief).sum())
    var = float((((CELLS - mean) ** 2) * belief).sum())
    return mean, math.sqrt(var)


belief = gaussian(CELLS, 0.0, START_SIGMA)
belief = belief / belief.sum()
kernel = make_kernel(MOTION_SIGMA)
for step in range(1, 11):
    belief = predict(belief, kernel)
    if step in (1, 5, 10):
        mean, sigma = stats(belief)
        kalman = math.sqrt(START_SIGMA ** 2 + step * MOTION_SIGMA ** 2)
        print("step", step, "mean", round(mean, 4), "grid sigma", round(sigma, 5), "kalman sigma", round(kalman, 5))

